def find_most_frequent_character(S: str) -> str:
    frequency = {}

    for char in S:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    most_frequent_char = S[0]

    for char in frequency:
        if (frequency[char] > frequency[most_frequent_char]) or \
           (frequency[char] == frequency[most_frequent_char] and char < most_frequent_char):
            most_frequent_char = char

    return most_frequent_char
